10	// 但不新增货物、不再次占用重量。更正不占用配载调整编号，也不影响已
11	// 成功调整保存的结果：之后以原编号、原内容重复提交调整，仍返回首次
12	// 成功时的变化与重量。更正前返回的查询或预览快照继续保留原内容。
13	//
14	// 未装载货物只需资料本身合法，更正后仍为未装载。已装载货物按三项新
15	// 资料共同生效后的最终配载判断，不会因修改某个字段的中间状态不合法
16	// 而拒绝最终合法的资料：所属舱位先扣除该货物旧重量、再计入新重量，
17	// 恰好达到承重允许保存，超过承重或合计无法用 int64 表示则拒绝；
18	// 同舱目的地全部相同时允许不混装的货物共舱，出现不同目的地时所有
19	// 货物都必须允许混装。
20	//
21	// 更正失败时，货物的三项旧资料、所属舱位重量及其他货物全部保留。
22	func (r *Registry) AmendCargo(id string, weight int64, destination string, allowMixed bool) error {
23		r.mu.Lock()
24		defer r.mu.Unlock()
25	
26		cid := trimID(id)
27		if cid == "" {
28			return fail(ErrInvalidID, "", "货物编号为空")
29		}
30		c, ok := r.cargos[cid]
31		if !ok {
32			return fail(ErrNotFound, cid, "货物 %s 不存在", cid)
33		}
34		if weight <= 0 {
35			return fail(ErrInvalidWeight, cid, "货物 %s 重量必须为正整数千克，当前为 %d", cid, weight)
36		}
37		dest := trimID(destination)
38		if dest == "" {
39			return fail(ErrInvalidDestination, cid, "货物 %s 目的地为空", cid)
40		}
41	
42		// 已装载货物：在所属舱位的模拟配载上替换该货物，按三项资料共同
43		// 生效后的最终状态统一判断，而不是逐个字段制造中间状态。
44		if c.compartmentID != "" {
45			comp := r.compartments[c.compartmentID]
46			sim := &cargo{
47				id:            c.id,
48				weight:        weight,
49				destination:   dest,
50				allowMixed:    allowMixed,
51				compartmentID: comp.id,
52			}
53			set := make(map[string]*cargo, len(comp.cargo))
54			for otherID, other := range comp.cargo {
55				if otherID == c.id {
56					set[c.id] = sim
57				} else {
58					set[otherID] = other
59				}
60			}
61			final := map[string]map[string]*cargo{comp.id: set}
62			// 拒绝原因到结构化错误的转换与 Adjust 共用；更正不携带调整编号。
