40	// cycleMovePermutations 返回三条循环移动操作的全部 6 种先后次序，用于
41	// 保护“操作在清单中的先后次序不影响能否提交、最终配载与按编号排列的
42	// 变化记录”。
43	func cycleMovePermutations() [][]Op {
44		base := []Op{
45			{Kind: OpMove, CargoID: "G1", Target: "C2"},
46			{Kind: OpMove, CargoID: "G2", Target: "C3"},
47			{Kind: OpMove, CargoID: "G3", Target: "C1"},
48		}
49		var out [][]Op
50		var perm func(int)
51		perm = func(start int) {
52			if start == len(base) {
53				out = append(out, append([]Op(nil), base...))
54				return
55			}
56			for i := start; i < len(base); i++ {
57				base[start], base[i] = base[i], base[start]
58				perm(start + 1)
59				base[start], base[i] = base[i], base[start]
60			}
61		}
62		perm(0)
63		return out
64	}
65	
66	// cycleExpectedCargoChanges 是循环换舱按货物编号排列的变化记录。
67	func cycleExpectedCargoChanges() []CargoChange {
68		return []CargoChange{
69			{CargoID: "G1", From: "C1", To: "C2"},
70			{CargoID: "G2", From: "C2", To: "C3"},
71			{CargoID: "G3", From: "C3", To: "C1"},
72		}
73	}
74	
75	// assertCycleCargoProfilesUnchanged 核对三件货物的重量、目的地与混装
76	// 许可始终保持登记原值，仅归属随调整改变。
77	func assertCycleCargoProfilesUnchanged(t *testing.T, r *Registry) {
78		t.Helper()
79		want := map[string]struct {
80			weight      int64
81			destination string
82		}{
83			"G1": {60, "上海"},
84			"G2": {80, "天津"},
85			"G3": {100, "广州"},
86		}
87		for id, w := range want {
88			cv, _ := r.Cargo(id)
89			if cv.Weight != w.weight || cv.Destination != w.destination || cv.AllowMixed {
90				t.Fatalf("货物 %s 的登记资料被改变: %+v", id, cv)
91			}
92		}
93	}
94	
95	// assertCycleActualStowage 核对登记处的实际配载：C1 只装 G1（已用 60、
96	// 剩余 c1Max-60），C2 只装 G2（80/20），C3 只装 G3（100/0），每件货物
97	// 的货物查询归属与所在舱清单一致，且三件货物在三舱清单中各出现一次，
98	// 重量、目的地与混装许可保持登记值。
99	func assertCycleActualStowage(t *testing.T, r *Registry, c1Max int64) {
100		t.Helper()
101		wantComps := []struct {
102			id        string
103			maxWeight int64
104			used      int64
105			remaining int64
106			cargo     []string
107		}{
108			{"C1", c1Max, 60, c1Max - 60, []string{"G1"}},
109			{"C2", 100, 80, 20, []string{"G2"}},
110			{"C3", 100, 100, 0, []string{"G3"}},
111		}
112		seen := make(map[string]string)
113		for _, wc := range wantComps {
114			cv, err := r.Compartment(wc.id)
115			if err != nil {
116				t.Fatalf("查询舱位 %s 失败: %v", wc.id, err)
117			}
118			if cv.MaxWeight != wc.maxWeight || cv.UsedWeight != wc.used ||
119				cv.RemainingWeight != wc.remaining ||
120				!reflect.DeepEqual(cargoIDs(*cv), wc.cargo) {
121				t.Fatalf("舱位 %s 实际配载错误: got=%+v want 承重=%d 已用=%d 剩余=%d 清单=%v",
122					wc.id, cv, wc.maxWeight, wc.used, wc.remaining, wc.cargo)
123			}
124			for _, c := range cv.Cargo {
125				if !c.Loaded || c.CompartmentID != wc.id {
126					t.Fatalf("舱位 %s 清单中的 %s 位置标记错误: loaded=%v comp=%q",
127						wc.id, c.ID, c.Loaded, c.CompartmentID)
128				}
129				if other, dup := seen[c.ID]; dup {
130					t.Fatalf("货物 %s 同时出现在 %s 与 %s 清单中", c.ID, other, wc.id)
131				}
132				seen[c.ID] = wc.id
133			}
134		}
135		if len(seen) != 3 {
136			t.Fatalf("三舱清单应恰好含三件货物，实际: %+v", seen)
137		}
138		wantAt := map[string]string{"G1": "C1", "G2": "C2", "G3": "C3"}
139		for id, wantComp := range wantAt {
140			cv, _ := r.Cargo(id)
141			if !cv.Loaded || cv.CompartmentID != wantComp {
142				t.Fatalf("货物 %s 应在 %s，实际 %q（loaded=%v）",
143					id, wantComp, cv.CompartmentID, cv.Loaded)
144			}
145			if seen[id] != wantComp {
146				t.Fatalf("货物查询 %s 在 %s，但舱位清单显示在 %s", id, wantComp, seen[id])
147			}
148		}
149		assertCycleCargoProfilesUnchanged(t, r)
150	}
151	
152	// assertCyclePreviewCompartments 核对循环换舱预览中三个受影响舱位完整的
153	// 调整前/预计清单、承重、已用与剩余重量：Before 保留各舱调整前清单且货物
154	// 标记为原舱；After 中货物一律显示已装载于新舱；登记资料不变。
155	// c1Max 为 C1 承重（100 合法、90 超重）；C1 超重时其预计剩余为 -10。
156	func assertCyclePreviewCompartments(t *testing.T, res *PreviewResult, c1Max int64) {
157		t.Helper()
158		if len(res.Compartments) != 3 {
159			t.Fatalf("预览应列出全部三个受影响舱位: %+v", res.Compartments)
160		}
161		want := []struct {
162			id                      string
163			maxWeight               int64
164			usedBefore, remBefore   int64
165			usedAfter, remAfter     int64
166			cargoBefore, cargoAfter []string
167		}{
168			{"C1", c1Max, 60, c1Max - 60, 100, c1Max - 100, []string{"G1"}, []string{"G3"}},
169			{"C2", 100, 80, 20, 60, 40, []string{"G2"}, []string{"G1"}},
170			{"C3", 100, 100, 0, 80, 20, []string{"G3"}, []string{"G2"}},
171		}
172		for i, wc := range want {
173			cp := res.Compartments[i]
174			if cp.ID != wc.id {
175				t.Fatalf("舱位应按编号字典序排列，第 %d 个应为 %s，实际 %s", i, wc.id, cp.ID)
176			}
177			b, a := cp.Before, cp.After
178			if b.MaxWeight != wc.maxWeight || b.UsedWeight != wc.usedBefore ||
179				b.RemainingWeight != wc.remBefore ||
180				!reflect.DeepEqual(cargoIDs(b), wc.cargoBefore) {
181				t.Fatalf("%s 调整前清单/重量错误: %+v", wc.id, b)
182			}
183			if a.MaxWeight != wc.maxWeight || a.UsedWeight != wc.usedAfter ||
184				a.RemainingWeight != wc.remAfter ||
185				!reflect.DeepEqual(cargoIDs(a), wc.cargoAfter) {
186				t.Fatalf("%s 预计清单/重量错误: %+v", wc.id, a)
187			}
188			// Before 中货物保留原所属舱位。
189			wantBeforeAt := map[string]string{"C1": "G1", "C2": "G2", "C3": "G3"}[wc.id]
190			for _, c := range b.Cargo {
191				if !c.Loaded || c.CompartmentID != wc.id || c.ID != wantBeforeAt {
192					t.Fatalf("%s 调整前清单应保留 %s 原位置: %+v", wc.id, wantBeforeAt, c)
193				}
194			}
195			// After 中货物一律显示已装载于该新舱。
196			for _, c := range a.Cargo {
197				if !c.Loaded || c.CompartmentID != wc.id {
198					t.Fatalf("%s 预计清单中的 %s 应显示已装载于 %s: %+v",
199						wc.id, c.ID, wc.id, c)
200				}
201			}
202		}
203		// 预计清单中的登记资料保持原值。
204		wantProfile := map[string]struct {
205			weight      int64
206			destination string
207		}{
208			"G1": {60, "上海"},
209			"G2": {80, "天津"},
210			"G3": {100, "广州"},
211		}
212		for _, cp := range res.Compartments {
213			for _, c := range cp.After.Cargo {
214				wp := wantProfile[c.ID]
215				if c.Weight != wp.weight || c.Destination != wp.destination || c.AllowMixed {
216					t.Fatalf("预计清单中 %s 的登记资料被改变: %+v", c.ID, c)
217				}
218			}
219		}
220	}
221	
222	// 三舱循环换舱的预览应判为可提交且没有拒绝原因：虽然逐条先移任何一件都会
223	// 让目标舱暂时超重（目标舱原货尚未移出）并混入不同目的地，最终配载却是
224	// C1=G3（广州）、C2=G1（上海）、C3=G2（天津），各舱一件、同一目的地。
225	// 预览完整保留各舱调整前清单，预计清单中的货物显示已装载于新舱；预览只读，
226	// 预览之后查询三件货物仍在原舱。该结论对三条操作的全部先后次序成立。
227	func TestPreviewCrossDestinationCycleSucceedsAndDoesNotApply(t *testing.T) {
228		for i, ops := range cycleMovePermutations() {
229			t.Run("次序", func(t *testing.T) {
230				r := newCrossDestinationCycleRegistry(t, 100)
231	
232				res, err := r.Preview(ops)
233				if err != nil {
234					t.Fatalf("第 %d 种次序：预览不应出错: %v", i, err)
235				}
236				if !res.Submittable {
237					t.Fatalf("第 %d 种次序：循环换舱按最终配载应可提交: %+v", i, res.Rejections)
238				}
239				if len(res.Rejections) != 0 {
240					t.Fatalf("第 %d 种次序：可提交预览不应有拒绝原因: %+v", i, res.Rejections)
241				}
242				if !reflect.DeepEqual(res.CargoChanges, cycleExpectedCargoChanges()) {
243					t.Fatalf("第 %d 种次序：货物变化错误: got=%+v want=%+v",
244						i, res.CargoChanges, cycleExpectedCargoChanges())
245				}
246				assertCyclePreviewCompartments(t, res, 100)
247	
248				// 预览只读：三件货物仍在原舱，三舱清单、已用与剩余重量不变。
249				assertCycleActualStowage(t, r, 100)
250			})
251		}
252	}
253	
254	// 正式提交循环换舱应成功。变化记录反映三件货物各自的原舱与新舱，以及三个
255	// 舱位准确的前后重量，均按编号排列；最终 C1、C2、C3 分别只装 G3、G1、G2，
256	// 已用 100、60、80，剩余 0、40、20。货物查询与舱位清单严格一致，每件只
257	// 出现一次，重量、目的地和混装许可保持登记值。三条操作的全部先后次序都
258	// 得到同一结论。
259	func TestAdjustCrossDestinationCycleSucceeds(t *testing.T) {
260		for i, ops := range cycleMovePermutations() {
261			t.Run("次序", func(t *testing.T) {
262				r := newCrossDestinationCycleRegistry(t, 100)
263	
264				res, err := r.Adjust("cycle-full", ops)
265				if err != nil {
266					t.Fatalf("第 %d 种次序：循环换舱按最终配载应合法，却被拒绝: %v", i, err)
267				}
268				if res == nil || res.ID != "cycle-full" {
269					t.Fatalf("第 %d 种次序：成功结果异常: %+v", i, res)
270				}
271				if !reflect.DeepEqual(res.CargoChanges, cycleExpectedCargoChanges()) {
272					t.Fatalf("第 %d 种次序：货物变化错误: got=%+v want=%+v",
273						i, res.CargoChanges, cycleExpectedCargoChanges())
274				}
275				// 三个舱位准确的前后重量，按舱位编号排列；即使没有舱位重量
276				// 相等也逐一核对。
277				wantCompChanges := []CompartmentChange{
278					{CompartmentID: "C1", WeightBefore: 60, WeightAfter: 100},
279					{CompartmentID: "C2", WeightBefore: 80, WeightAfter: 60},
280					{CompartmentID: "C3", WeightBefore: 100, WeightAfter: 80},
281				}
282				if !reflect.DeepEqual(res.CompartmentChanges, wantCompChanges) {
283					t.Fatalf("第 %d 种次序：舱位重量变化错误: got=%+v want=%+v",
284						i, res.CompartmentChanges, wantCompChanges)
285				}
286	
287				// 最终配载：C1=G3（100/0）、C2=G1（60/40）、C3=G2（80/20）。
288				wantFinal := []struct {
289					id              string
290					used, remaining int64
291					cargo           []string
292				}{
293					{"C1", 100, 0, []string{"G3"}},
294					{"C2", 60, 40, []string{"G1"}},
295					{"C3", 80, 20, []string{"G2"}},
296				}
297				for _, wc := range wantFinal {
298					cv, _ := r.Compartment(wc.id)
299					if cv.MaxWeight != 100 || cv.UsedWeight != wc.used ||
300						cv.RemainingWeight != wc.remaining ||
301						!reflect.DeepEqual(cargoIDs(*cv), wc.cargo) {
302						t.Fatalf("第 %d 种次序：%s 最终配载错误: %+v", i, wc.id, cv)
303					}
304				}
305	
306				// 货物查询与舱位清单一致：每件只出现一次、只在一个舱。
307				wantAt := map[string]string{"G1": "C2", "G2": "C3", "G3": "C1"}
308				counts := make(map[string]int)
309				for _, id := range []string{"C1", "C2", "C3"} {
310					cv, _ := r.Compartment(id)
311					if len(cv.Cargo) != 1 {
312						t.Fatalf("第 %d 种次序：%s 最终应只装一件货物: %+v", i, id, cv.Cargo)
313					}
314					counts[cv.Cargo[0].ID]++
315				}
316				for id, wantComp := range wantAt {
317					cv, _ := r.Cargo(id)
318					if !cv.Loaded || cv.CompartmentID != wantComp {
319						t.Fatalf("第 %d 种次序：货物 %s 应在 %s，实际 %q（loaded=%v）",
320							i, id, wantComp, cv.CompartmentID, cv.Loaded)
321					}
322					if counts[id] != 1 {
323						t.Fatalf("第 %d 种次序：货物 %s 应在舱位清单中恰好出现一次，实际 %d 次",
324							i, id, counts[id])
325					}
326				}
327				assertCycleCargoProfilesUnchanged(t, r)
328			})
329		}
330	}
331	
332	// 保持同样的初始货物与换舱安排，只把 C1 承重设为 90：初始装载仍合法
333	// （G1 仅 60），但循环后 C1 将装 G3（100），超重 10 千克。预览应判为
334	// 不可提交，仍给出完整预计配载与货物变化，拒绝原因指出 C1 超重 10 千克、
335	// 预计已用 100、预计剩余 -10，且不夹带混装原因；预览不落地，三件货物仍在
336	// 原舱。三条操作的全部先后次序结论一致。
337	func TestPreviewCrossDestinationCycleOverweightRejected(t *testing.T) {
338		for i, ops := range cycleMovePermutations() {
339			t.Run("次序", func(t *testing.T) {
340				r := newCrossDestinationCycleRegistry(t, 90)
341				compBefore := snapshotCompartments(r, "C1", "C2", "C3")
342				cargoBefore := snapshotCargo(r, "G1", "G2", "G3")
343	
344				res, err := r.Preview(ops)
345				if err != nil {
346					t.Fatalf("第 %d 种次序：预览不应出错: %v", i, err)
347				}
348				if res.Submittable || len(res.Rejections) != 1 {
349					t.Fatalf("第 %d 种次序：应不可提交且恰有一条拒绝原因: %+v", i, res)
350				}
351				rej := res.Rejections[0]
352				if rej.Kind != ErrOverweight || rej.CompartmentID != "C1" ||
353					rej.MaxWeight != 90 || rej.UsedWeight != 100 ||
354					rej.RemainingWeight != -10 || rej.Overweight != 10 {
355					t.Fatalf("第 %d 种次序：C1 超重原因内容错误: %+v", i, rej)
356				}
357				if len(rej.Destinations) != 0 || len(rej.OffendingCargo) != 0 {
358					t.Fatalf("第 %d 种次序：超重原因不应携带混装信息: %+v", i, rej)
359				}
360	
361				// 即使不可提交，完整预计配载与货物变化仍照常返回。
362				if !reflect.DeepEqual(res.CargoChanges, cycleExpectedCargoChanges()) {
363					t.Fatalf("第 %d 种次序：超重时仍应给出货物变化: got=%+v", i, res.CargoChanges)
364				}
365				assertCyclePreviewCompartments(t, res, 90)
366	
367				// 预览只读：三舱实际清单、已用与剩余重量及货物归属保持调整前状态。
368				assertCompartmentsUnchanged(t, r, compBefore)
369				assertCargoUnchanged(t, r, cargoBefore)
370				assertCycleActualStowage(t, r, 90)
371			})
372		}
373	}
374	
375	// C1 承重为 90 时正式提交必须按 C1 超重整次拒绝：结构化错误为
376	// ErrOverweight、指向 C1、携带调整编号，说明给出预计总重 100 千克与
377	// 承重 90 千克，不返回成功结果。整批原子：三条操作的任何先后次序下，
378	// 三件货物的位置、三舱实际清单、已用与剩余重量都完全保留调整前状态，
379	// 不能先完成部分换舱。失败不占用编号：以同一编号重提仍得到超重拒绝
380	// 而非编号冲突。
381	func TestAdjustCrossDestinationCycleOverweightRejectedAtomically(t *testing.T) {
382		for i, ops := range cycleMovePermutations() {
383			t.Run("次序", func(t *testing.T) {
384				r := newCrossDestinationCycleRegistry(t, 90)
385				compBefore := snapshotCompartments(r, "C1", "C2", "C3")
386				cargoBefore := snapshotCargo(r, "G1", "G2", "G3")
387	
388				se := submitExpectReject(t, r, "cycle-over", ops)
389				if se.Kind != ErrOverweight {
390					t.Fatalf("第 %d 种次序：应按超重拒绝，实际 Kind=%s", i, se.Kind)
391				}
392				if se.ID != "C1" {
393					t.Fatalf("第 %d 种次序：超重原因应指向舱位 C1，实际 ID=%q", i, se.ID)
394				}
395				if se.AdjustmentID != "cycle-over" {
396					t.Fatalf("第 %d 种次序：错误应携带调整编号 cycle-over，实际 %q",
397						i, se.AdjustmentID)
398				}
399				msg := se.Error()
400				if !strings.Contains(msg, "C1") ||
401					!strings.Contains(msg, "100") || !strings.Contains(msg, "90") {
402					t.Fatalf("第 %d 种次序：超重说明应指出 C1、预计总重 100 与承重 90: %s",
403						i, msg)
404				}
405	
406				// 整次调整不生效：三件货物仍在原舱，三舱重量不变。
407				assertCompartmentsUnchanged(t, r, compBefore)
408				assertCargoUnchanged(t, r, cargoBefore)
409				assertCycleActualStowage(t, r, 90)
410	
411				// 失败的调整不占用编号：以同一编号重提仍是超重拒绝而不是编号冲突，
412				// 状态继续保持原样，证明任何一种操作次序都没有先完成部分换舱。
413				again := submitExpectReject(t, r, "cycle-over", ops)
414				if again.Kind != ErrOverweight || again.ID != "C1" ||
415					again.AdjustmentID != "cycle-over" {
416					t.Fatalf("第 %d 种次序：同编号重提应仍为超重拒绝: %+v", i, again)
417				}
418				assertCompartmentsUnchanged(t, r, compBefore)
419				assertCargoUnchanged(t, r, cargoBefore)
420				assertCycleActualStowage(t, r, 90)
421			})
422		}
423	}
