			cv.AllowMixed != inList.AllowMixed || cv.CompartmentID != inList.CompartmentID {
			t.Fatalf("货物查询与舱位清单对 %s 的记载不一致: 查询=%+v 清单=%+v", id, cv, inList)
		}
	}
